INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (1, 0, 0, 190804, 1, 0, 60000, 1, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (2, 1, 0, 0, 1, 0, 60000, 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (3, 1, 0, 0, 1, 0, 60000, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (4, 1, 0, 0, 2, 0, 60000, 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (5, 2, 0, 0, 1, 0, 60000, 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (6, 2, 0, 0, 1, 0, 60000, 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (7, 2, 0, 0, 2, 0, 60000, 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (8, 3, 0, 0, 1, 0, 60000, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (9, 3, 0, 0, 1, 0, 60000, 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (10, 3, 0, 0, 1, 0, 60000, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (11, 3, 0, 0, 1, 0, 60000, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (12, 3, 0, 0, 2, 0, 60000, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (13, 4, 0, 0, 1, 0, 60000, 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (14, 4, 0, 0, 1, 0, 60000, 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (15, 4, 0, 0, 1, 0, 60000, 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (16, 4, 0, 0, 1, 0, 60000, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (17, 4, 0, 0, 2, 0, 60000, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (18, 0, 0, 190804, 0, 0, 60000, 2, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (19, 0, 0, 190804, 0, 7, 60000, 3, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (20, 0, 0, 101201, 0, 1, 80001, 1, "キミと出会ってもう\n1年もたつんだね！\nう～ん、いつも\n寝てばっかりだから、", "ハツネ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (21, 0, 0, 101201, 0, 1, 80001, 2, "少しでも\n寝る時間を減らして\nキミと一緒にいる\n時間増やしたいなぁ♪", "ハツネ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (22, 0, 0, 103801, 0, 1, 80001, 1, "あなたと知り合ってから\nもう1年…\n時がたつのは\n早いですね", "シオリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (23, 0, 0, 103801, 0, 1, 80001, 2, "来年も、\n一緒にいられたら…\nうれしいな", "シオリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (24, 0, 0, 103601, 0, 2, 80001, 1, "あなたと一緒にいるようになって、\nもう1年ですか…", "キョウカ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (25, 0, 0, 103601, 0, 2, 80001, 2, "最初の頃よりも、頼もしく\nなりましたね。私はどうですか？\n成長していますか？", "キョウカ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (26, 0, 0, 102001, 0, 2, 80001, 1, "おにいちゃんとあってから、\n1年たったよ～！", "ミミ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (27, 0, 0, 102001, 0, 2, 80001, 2, "ミミね、おにいちゃんと\nいっぱい遊べてたのしかったな～♪\nこれからもずっと\nいっしょにいてね～！", "ミミ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (28, 0, 0, 100401, 0, 2, 80001, 1, "にいちゃんがミソギのイタズラに\n引っかかり続けてもう1年かぁ", "ミソギ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (29, 0, 0, 100401, 0, 2, 80001, 2, "…これからもいっぱいミソギと\n遊んでね、にいちゃん！", "ミソギ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (30, 0, 0, 101001, 0, 3, 80001, 1, "もう王子はんと会うてから\n1年ぐらいたつそうどすえ\n早いもんやなあ", "マホ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (31, 0, 0, 101001, 0, 3, 80001, 2, "このままやと、\nうちもあっという間に\n干からびてしまいそうどすえ\nなーんてな。うふふ", "マホ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (32, 0, 0, 104401, 0, 3, 80001, 1, "お主と会って早1年じゃな\nこれからも存分に尽くすがよい", "イリヤ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (33, 0, 0, 104401, 0, 3, 80001, 2, "わらわもたまには、お主の献身に\n報いてやらぬでもない♪", "イリヤ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (34, 0, 0, 101701, 0, 3, 80001, 1, "もう、キミと出会って結構な時間が\nたつさ～。でも、私たちの旅は\nまだまだ始まったばかりさ～！", "カオリ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (35, 0, 0, 101701, 0, 3, 80001, 2, "これからも、どうぞよろしく\nお願いするさ～！", "カオリ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (36, 0, 0, 102801, 0, 4, 80001, 1, "あんたと出会ってからもうそんなに\nたつのね～", "サレン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (37, 0, 0, 102801, 0, 4, 80001, 2, "あっという間だったって感じるほど\n楽しかったわ！\nこれからも一緒に頑張りましょ！", "サレン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (38, 0, 0, 102501, 0, 4, 80001, 1, "出会ってから1年間、ずっと\nご迷惑をかけっぱなしで、\nすみません…", "スズメ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (39, 0, 0, 102501, 0, 4, 80001, 2, "これからはもっと頑張りますから\n見ていてくださいね\nできれば…\n今までよりも、私の近くで♪", "スズメ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (40, 0, 0, 104601, 0, 5, 80001, 1, "振り返れば、今までいろんなことが\nあったにゃあ…", "タマキ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (41, 0, 0, 104601, 0, 5, 80001, 2, "これからも、二人でたくさんの\n思い出をがっぽり作っていく\nにゃー！", "タマキ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (42, 0, 0, 104801, 0, 5, 80001, 1, "キミとの師弟関係も、\nもう1年なのね…\nでもキミに教えることは、", "ミフユ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (43, 0, 0, 104801, 0, 5, 80001, 2, "まだまだいっぱいあるわ\nこれからも、\nしっかりついて来てね！", "ミフユ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (44, 0, 0, 103201, 0, 6, 80001, 1, "あなたさまと出会ってもう1年…", "アキノ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (45, 0, 0, 103201, 0, 6, 80001, 2, "光陰矢のごとし、とはまさに\nこのことですわ。…思い出は決して\nお金では買えませんわね", "アキノ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (46, 0, 0, 103401, 0, 6, 80001, 1, "ダメな私を1年間も見捨てないで\nくれて、本当にありがとう", "ユカリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (47, 0, 0, 103401, 0, 6, 80001, 2, "情けないところいっぱいみせるかも\nしれないけど、これからも一緒に\nいてくれると、うれしいな", "ユカリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (48, 0, 0, 107101, 0, 7, 80001, 1, "オマエと出会ってもう1年か\nまさかこのワタシの結婚相手に\nなろうとはな…", "クリスティーナ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (49, 0, 0, 107101, 0, 7, 80001, 2, "ともかくこれからも\n愉しませてくれよ☆", "クリスティーナ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (50, 0, 0, 104701, 0, 7, 80001, 1, "君と出会ってからもう1年か。\n以前と比べて私の表情もいくらか\n柔らかくなった気がするんだが、\nどうだろう？", "ジュン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (51, 0, 0, 104701, 0, 7, 80001, 2, "見えないから分からないって？\nそれもそうだな…", "ジュン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (52, 0, 0, 103701, 0, 8, 80001, 1, "もう1年たったみたいだね\nあなたをからかってばかりだった\nけど、楽しかった♪", "トモ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (53, 0, 0, 103701, 0, 8, 80001, 2, "これからもよろしくね！", "トモ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (54, 0, 0, 100501, 0, 8, 80001, 1, "出会って、もう1年たっちゃった\nんスね。なんだか意外ッス", "マツリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (55, 0, 0, 100501, 0, 8, 80001, 2, "毎日楽しくて、あっという間に過ぎ\nちゃったみたいなんスよね\nこれからも一緒に悪と戦うッス！", "マツリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (56, 0, 0, 100701, 0, 9, 80001, 1, "オマエと会って1年なの！\n全然成仏もできなかったし、", "ミヤコ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (57, 0, 0, 100701, 0, 9, 80001, 2, "生き返りもしなかったけど、\nすごく楽しかったの～♪\nオマエとプリンがあれば、\nミヤコはハッピーなの～♪", "ミヤコ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (58, 0, 0, 103101, 0, 9, 80001, 1, "あなたと出会って1年なんですね\nでも、私の占いでは、私とあなたは", "シノブ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (59, 0, 0, 103101, 0, 9, 80001, 2, "来年も再来年も一緒にいるようです\nふふ、よろしくお願いしますね", "シノブ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (60, 0, 0, 100901, 0, 10, 80001, 1, "貴様が閃光のシグルドとして覚醒し\nもう1年か…。これからも我らの\n長き戦いに終わりはないが、", "アンナ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (61, 0, 0, 100901, 0, 10, 80001, 2, "それでも貴様となら…\n添い遂げる覚悟はできているぞ！", "アンナ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (62, 0, 0, 101301, 0, 10, 80001, 1, "君と出会ってもう1年だって！\n早いねー！", "ナナカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (63, 0, 0, 101301, 0, 10, 80001, 2, "これからも最強のバディタッグで\n大活躍だー！\n頼りにしてるよ、相棒！", "ナナカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (64, 0, 0, 105101, 0, 11, 80001, 1, "1年たつのって、あっという間ね\nまだまだ君の知らない部分が\nたくさんあるし…", "ミツキ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (65, 0, 0, 105101, 0, 11, 80001, 2, "これからも、いろんなところを\n調べさせてね？", "ミツキ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (66, 0, 0, 105601, 0, 11, 80001, 1, "お前さんと出会ってもう1年か\n助太刀するつもりが", "ルカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (67, 0, 0, 105601, 0, 11, 80001, 2, "逆に助けられたりもしたね\nこれからもよろしく頼むよ！", "ルカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (68, 0, 0, 102701, 0, 11, 80001, 1, "早いものですわね、あなた様と\nお会いして、もう1年…", "エリコ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (69, 0, 0, 102701, 0, 11, 80001, 2, "あなた様といると、時があっと\nいう間に過ぎてしまいます\n時間を止める研究をしなくては\nいけませんね…", "エリコ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (70, 0, 0, 102301, 0, 12, 80001, 1, "お兄ちゃんと会ってから、もう、\n1年なんだね。私、少しは\nお姉ちゃんっぽくなったかな？", "アヤネ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (71, 0, 0, 102301, 0, 12, 80001, 2, "あ、ぷうきちもお兄ちゃんっぽく\nなったよね？", "アヤネ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (72, 0, 0, 104201, 0, 12, 80001, 1, "あなたと出会って、\nもう1年がたったんですね…\nこれからもそばにいて、", "チカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (73, 0, 0, 104201, 0, 12, 80001, 2, "私のことを見守ってください\nできることなら、ずっと…", "チカ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (74, 0, 0, 102101, 0, 12, 80001, 1, "お兄ちゃんと出会って1年かぁ\n私、相変わらずダメダメで…", "クルミ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (75, 0, 0, 102101, 0, 12, 80001, 2, "で、でもこれからもずっと…\n一緒にいたいなぁ…", "クルミ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (76, 0, 0, 104901, 0, 13, 80001, 1, "再会してちょうど1年だね\nお祝いにごちそう作ってきたよ～♪\n特製ケーキと、お寿司と、", "シズル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (77, 0, 0, 104901, 0, 13, 80001, 2, "ハンバーグと、カレーと、\nシチューと、あ、隠しきれない隠し\n味は、お姉ちゃんの愛情だよ！", "シズル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (78, 0, 0, 101101, 0, 13, 80001, 1, "お兄ちゃんと再会して、もう1年\nなんですね。\n会えなかった時を思うと、", "リノ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (79, 0, 0, 101101, 0, 13, 80001, 2, "信じられないくらい幸せな1年\nでした！もう絶対、私から離れ\nないでくださいね♪", "リノ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (80, 0, 0, 100201, 0, 14, 80001, 1, "騎士クンと出会ってから今まで、\nいろんなことがあったよね\n楽しいこと、ドキドキしたこと…", "ユイ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (81, 0, 0, 100201, 0, 14, 80001, 2, "そんな日々をこれからも、\nず、ずっと一緒に…\n過ごしていきたいな…！", "ユイ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (82, 0, 0, 100101, 0, 14, 80001, 1, "騎士くんと出会って、まだ1年しか\nたってないんだ！？", "ヒヨリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (83, 0, 0, 100101, 0, 14, 80001, 2, "なんかもうずっと一緒にいる気が\nするなぁ…えへへ。これからの\n1年もまたよろしくねっ！\n騎士くん！", "ヒヨリ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (84, 0, 0, 100301, 0, 14, 80001, 1, "初めてキミに出会って1年…\n随分見違えたね私もキミも、\n更に強くなっていく…", "レイ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (85, 0, 0, 100301, 0, 14, 80001, 2, "キミに背中を預けられる日が、\n早くきますように", "レイ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (86, 0, 0, 105801, 0, 15, 80001, 1, "1年もわたしのことを、忘れない\nでいてくれて、ありがとうござい\nます！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (87, 0, 0, 105801, 0, 15, 80001, 2, "これからもずっと、覚えていて\nくださいね！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (88, 0, 0, 105901, 0, 15, 80001, 1, "こうして1年も、主さまのおそばに\n置いていただけて、とても光栄\nです。どうかこれからも、", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (89, 0, 0, 105901, 0, 15, 80001, 2, "末永く主さまをお世話させて\nください。わたくしは、ずっと\n主さまのガイド役でいたいのです", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (90, 0, 0, 106001, 0, 15, 80001, 1, "1年か、まっさかこんなに長い\n付き合いになるなんてね～\nでも…わりと楽しい1年だったかも", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (91, 0, 0, 106001, 0, 15, 80001, 2, "だから、もうしばらくあんたに\n付き合ってやるわよ喜びなさい！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (92, 0, 0, 112101, 1, 0, 60001, 1, "新しい年のはじめに、\nおみくじはいかがでしょうか？\nよい運勢であるほど、\n沢山プレゼントが貰えますよ♪", "スズメ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (93, 1, 0, 0, 1, 0, 60001, 0, "今日の運勢は姫吉！　あらゆる運気が最大を示しています！　　　今なら「伝説の吸血鬼」をも従え、世界征服も夢じゃありません！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (94, 1, 0, 0, 1, 0, 60001, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (95, 1, 0, 0, 1, 0, 60001, 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (96, 1, 0, 0, 1, 0, 60001, 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (97, 1, 0, 0, 2, 0, 60001, 0, "今日の運勢は姫吉！　その高い運気はまさにショーグンの如く！　その溢れる威光は人々を惹きつけ、皆の人気者間違いなしです！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (98, 2, 0, 0, 1, 0, 60001, 0, "今日の運勢は大吉！　運気がどんどん高まっています！　　　　　何をやっても、最大効率で素晴らしい結果になりますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (99, 2, 0, 0, 1, 0, 60001, 0, "今日の運勢は大吉！　なにをやっても上手くいって大活躍！　　　そんな素敵なあなたを見て、後ろから誰かが……クスクス♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (100, 2, 0, 0, 1, 0, 60001, 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (101, 2, 0, 0, 1, 0, 60001, 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (102, 2, 0, 0, 2, 0, 60001, 0, "今日の運勢は大吉！　運気が高く、何かに挑戦すると良い結果に！隠れた才能が引き出されそう！　目指せヒデサ……ではなく秀才！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (103, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたいやき！　和菓子パワーで売上アップです！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (104, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　旅行運がぐんぐんと上昇中♪　　　　　　　もしかしたら、あの「マホマホ王国」にだって行けるかも♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (105, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (106, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (107, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　お出かけした先で良縁に恵まれそうです！　ダウナー系あざとい女子が、あま～い飴をくれるかも？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (108, 3, 0, 0, 1, 0, 60001, 0, "今日の運勢は中吉！　大抵のことはゴリ押しでなんとかできます！ラッキープレイスはゲーセン。パンチングマシンでストレス発散！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (109, 3, 0, 0, 2, 0, 60001, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかの如く、色々な事がうまくいきますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (110, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　早朝に幸運の兆しあり！　　　　　　　　　もしかしたら、優しいお姉ちゃんが起こしにきてくれますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (111, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　運気上昇中ですが、上がるまでが要注意！　ラッキーアニマルは熊！　本当の家族のように守ってくれるかも♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (112, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　外に出てゆっくり過ごすと運気が上昇！　　ラッキースポットは牧場。面白い出会いがありそうです♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (113, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (114, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (115, 4, 0, 0, 1, 0, 60001, 0, "今日の運勢は小吉！　思わぬ相手と仲良くなれるかも？　　　　　うっかり毒舌をもらしてしまわないように要注意です！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (116, 4, 0, 0, 2, 0, 60001, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (117, 0, 0, 112101, 0, 0, 60001, 2, "おみくじの結果はいかがでしたか？\n新たに始まる一日が、\nあなたにとってよい日になりますように\n明日もお待ちしていますね♪", "スズメ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (118, 0, 0, 112101, 0, 7, 60001, 3, "おみくじ、楽しんで頂けましたか？\nあなたの新しい年が\n素晴らしいものになるよう、\n心からお祈りしますね", "スズメ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (119, 0, 0, 105801, 0, 1, 80003, 1, "ヒューヒュー♪\nドンドンパフパフー♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (120, 0, 0, 105901, 0, 1, 80003, 1, "ひゅーひゅー\nどんどんぱふぱふー\nでございます", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (121, 0, 0, 105901, 0, 1, 80003, 2, "さぁ、キャルさまもご一緒に\nどんどんぱふぱふいたしましょう", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (122, 0, 0, 106001, 0, 1, 80003, 1, "え？　ちょっと\nいきなりなにっ？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (123, 0, 0, 106001, 0, 1, 80003, 2, "ドンドンパフパフってなんなの？\nあたしにも分かるように\nちゃんと説明しなさいっての！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (124, 0, 0, 105801, 0, 1, 80003, 2, "実はですねキャルちゃん！\nもうすぐわたしたちにとっての\n大切な節目──", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (125, 0, 0, 105801, 0, 1, 80003, 3, "『プリンセスコネクト！\nRe:Dive』\n2.5周年なんですよ！\nやばいですね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (126, 0, 0, 105901, 0, 1, 80003, 3, "ですからその日に向けて\n今から気分を盛り上げているのです", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (127, 0, 0, 106001, 0, 1, 80003, 3, "ああ、そういえば\nそんな時期だっけ\nって言っても、もう少し先じゃない\n気が早いんじゃないの？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (128, 0, 0, 105901, 0, 1, 80003, 4, "いいえ、キャルさま\nこういったお祝いは準備から\n楽しむものでございます\nそうですよね、ペコリーヌさま", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (129, 0, 0, 105801, 0, 1, 80003, 4, "その通りです♪　というわけで！\nカウントダウンの始まりですよ！\nみんなで一緒に2.5周年に向けて\n盛り上がっていきましょー☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (130, 0, 0, 106001, 0, 1, 80003, 4, "ド、ドンドンパフパフ～\nって何言わせんのよ！\nまったくもう、浮かれちゃってさ", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (131, 0, 0, 105901, 0, 1, 80003, 5, "ふふ。キャルさまもワクワクして\nおいでのようですね\nそれでは主さま。大切な記念日まで\nどうぞご期待くださいませ", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (132, 0, 0, 106001, 0, 2, 80003, 5, "記念日を盛り上げるったって\n一体どうしたらいいのよ？\nあたし、そういうの\n苦手なんだけど…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (133, 0, 0, 190801, 0, 2, 80003, 1, "あら、キャルさん\nどうかなさいましたか？\n何かお困りのようですけど", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (134, 0, 0, 106001, 0, 2, 80003, 6, "げっ…カリンじゃない\nなんでもないわよ！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (135, 0, 0, 190801, 0, 2, 80003, 2, "そうなのですか？\nキャルさんのことですからてっきり\n2.5周年をどう盛り上げたら\nいいか悩んでいるのかと…", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (136, 0, 0, 106001, 0, 2, 80003, 7, "分かってんじゃないのよ！？\nいっ、いや、違うけどね！\nあたしは別にそんなことで\n悩んでないわよっ？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (137, 0, 0, 190801, 0, 2, 80003, 3, "ふふっ…\nこういう時は、真心を込めて\n気持ちをそのまま口にしたら\nいいのではないでしょうか？", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (138, 0, 0, 106001, 0, 2, 80003, 8, "気持ちを、ねぇ\nそれが一番難しいんじゃない…\nそもそも、あたしは記念日とか\n別にどうだっていいし", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (139, 0, 0, 106001, 0, 2, 80003, 9, "…まあ、ペコリーヌもコロ助も\nやけに楽しそうだったから…\nこういうお祭り騒ぎみたいなのも\nたまにはいいかな、とは思うけど", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (140, 0, 0, 190801, 0, 2, 80003, 4, "なるほどなるほど～\nキャルさんは【美食殿】で祝う\n2.5周年を心から楽しみに\nしている、ということですね！", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (141, 0, 0, 106001, 0, 2, 80003, 10, "はぁ！？\nどこ聞いたらそうなるのよ！\nあたしは別に楽しみになんか…！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (142, 0, 0, 190801, 0, 2, 80003, 5, "キャルさんの心からの想い\nみなさんにも伝わったでしょうか？\n私も2.5周年が楽しみです！\n以上、カリンがお伝えしました！", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (143, 0, 0, 106001, 0, 2, 80003, 11, "心からの想いって何なのよ！？\n勝手に人の言葉を\n捻じ曲げんじゃないわよ！\nこのくそ眼鏡ーーーっ！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (144, 0, 0, 105901, 0, 3, 80003, 6, "ペコリーヌさま、もうすぐ\n記念日でございますね\nこういった節目というのは\n感慨深いものでございます", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (145, 0, 0, 105801, 0, 3, 80003, 5, "色んな思い出が蘇ってきますね！\n楽しい出来事が\nいっぱいありました♪", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (146, 0, 0, 105901, 0, 3, 80003, 7, "はい、そうでございますね\n主さまも【美食殿】の活動の他にも\nいろんなご経験をされたと\n聞いておりますよ", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (147, 0, 0, 105901, 0, 3, 80003, 8, "たしか…ランドソルで話題沸騰と\nなっていた、魔法少女なるものに\nお会いになられたとか", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (148, 0, 0, 105801, 0, 3, 80003, 6, "魔法少女って、あの美味しくって\n栄養たっぷりの大ヒット商品\n『魔法少女ソーセージ』の箱に\n描いてある女の子のことですか！？", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (149, 0, 0, 105801, 0, 3, 80003, 7, "あのソーセージ\n美味しいんですよね～♪\nわたしもたっくさん食べてますよ！", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (150, 0, 0, 105901, 0, 3, 80003, 9, "あとは、牧場に素敵な温泉が\n出来たとか…", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (151, 0, 0, 105801, 0, 3, 80003, 8, "牧場ですか！？　温泉につかって\nチーズもオツですね～♪　考えた\nだけでよだれが出ちゃいそうです！\nやばいですね☆", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (152, 0, 0, 105901, 0, 3, 80003, 10, "ペコリーヌさま\n言ってるそばからよだれが…\n今お拭きしますね。ふき、ふき", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (153, 0, 0, 105801, 0, 3, 80003, 9, "えへへ、ありがとうございます\nコッコロちゃん！", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (154, 0, 0, 105901, 0, 3, 80003, 11, "それにしても、主さまは\n【美食殿】の一員として様々な\n美食と出会われていたのですね\nわたくし、感服いたしました", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (155, 0, 0, 105801, 0, 3, 80003, 10, "これからもたくさん冒険をして\nめいっぱい美食を\n味わい尽くしましょうね！", "ペコリーヌ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (156, 0, 0, 105801, 0, 4, 80003, 11, "2.5周年カウントダウン♪\nキャルちゃんキャルちゃん！\nわくわくしますね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (157, 0, 0, 106001, 0, 4, 80003, 12, "あぁもう、うるさいわね～\nまだまだ先でしょ？\nちょっとは落ち着きなさいよ", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (158, 0, 0, 105801, 0, 4, 80003, 12, "キャルちゃんだって最近\nソワソワしてるじゃないですか～\nさっきもご機嫌そうに鼻歌とか\n歌ってましたよね？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (159, 0, 0, 106001, 0, 4, 80003, 13, "なっ…！　き、聞いてたの！？\nじゃない、歌ってないわよ！？\nあんたいい加減なこと言うと\nぶっ殺すわよ！？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (160, 0, 0, 105801, 0, 4, 80003, 13, "えっへへ～♪\nわたしは最近のキャルちゃんが\nもっともっと大好きですよ♪\nすごく積極的になりましたよね！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (161, 0, 0, 106001, 0, 4, 80003, 14, "…積極的？\nなんの話よ？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (162, 0, 0, 105801, 0, 4, 80003, 14, "またまた～♪\nアイドルを目指そうとしたこと\n忘れちゃったんですか？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (163, 0, 0, 105801, 0, 4, 80003, 15, "ムーサの町で\nきゃるきゃる～ん☆　って！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (164, 0, 0, 106001, 0, 4, 80003, 15, "あっ…！？　ちちち違うわよっ！\nあれは操られてただけで\nあたしはアイドルなんか\n目指してないっての！！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (165, 0, 0, 105801, 0, 4, 80003, 16, "本当に本当ですか？\nわたし、キャルちゃんとっても\n乗り気だなって\n思ってたんですけど～", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (166, 0, 0, 106001, 0, 4, 80003, 16, "まぁ、悪くはなかったけど…って\nだ、だから目指してないって\n言ってるでしょ！！\nなんてこと思い出させんのよ！？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (167, 0, 0, 106001, 0, 4, 80003, 17, "ああ…ダメだわ…\nもう殺すしかない…\n2.5周年が来る前に\n記憶ごと消し去ってやるー！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (168, 0, 0, 106001, 0, 5, 80003, 18, "2.5周年まであと10日…\nふ～ん？\n案外早いもんね？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (169, 0, 0, 105901, 0, 5, 80003, 12, "そうでございますね…\nその日のためにやるべきことは\nまだまだございます\n気を引き締めねばなりません…！", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (170, 0, 0, 106001, 0, 5, 80003, 19, "やる気十分ねコロ助…\nそんな気負ってるとしんどいわよ？\nお気楽にやりましょ？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (171, 0, 0, 105901, 0, 5, 80003, 13, "キャルさま…\nありがとうございます\nキャルさまは本当に\n優しいおかたです", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (172, 0, 0, 106001, 0, 5, 80003, 20, "な、なにわけの分かんないこと\n言ってんのよ…\nあたしは優しくなんかないっての", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (173, 0, 0, 105901, 0, 5, 80003, 14, "そんなことはございません\n…あの、実はわたくし\nキャルさまに\nひとつお願いがございまして", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (174, 0, 0, 106001, 0, 5, 80003, 21, "お願い？　珍しいわね\nコロ助がそんなこと言うなんて\n…まあ、あたしに出来ることなら\n別にいいけど", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (175, 0, 0, 105901, 0, 5, 80003, 15, "ありがとうございます\n実は記念日へ向けて\n『かくし芸』というものを\n用意してみようかと思いまして", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (176, 0, 0, 106001, 0, 5, 80003, 22, "かくし芸？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (177, 0, 0, 105901, 0, 5, 80003, 16, "はい。きゃるきゃる～ん☆　を\n参考に、ころころ～ん☆　という\nご挨拶を考えてみたのですが\nポーズがうまくいかなくて…", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (178, 0, 0, 106001, 0, 5, 80003, 23, "～～！！　ちょっと褒められて\nいい気になって損したわ！！\nふざけんなふざけんな\nふ～ざ～け～ん～な～っ！！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (179, 0, 0, 105801, 0, 6, 80003, 17, "あと９日！　もうすぐですよ♪\nえへへ、楽しみで楽しみで\nごはんが進みますね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (180, 0, 0, 106001, 0, 6, 80003, 24, "ごはんが進みますね☆\nじゃなーい！\nいくらなんでも食べ過ぎよ！\n記念日、迎えられなくなるわよ！？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (181, 0, 0, 105901, 0, 6, 80003, 17, "大丈夫ですよキャルさま\n食事はわたくしたちの\n歩んできた道そのもの\nなのですから", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (182, 0, 0, 105801, 0, 6, 80003, 18, "さっすがコッコロちゃん\nいいことを言いますね！\nそう、わたしたち\n【美食殿】の活動目的は─", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (183, 0, 0, 106001, 0, 6, 80003, 25, "─みんなで楽しく食事をすること\nでしょ？\nあれだけ食べ歩いてきたんだから\n分かってるわよ", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (184, 0, 0, 105901, 0, 6, 80003, 18, "はい…そうでございますね♪\nそれにしてもわたくしたち\n本当にいろいろなものを\n食べ歩いてきましたね…", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (185, 0, 0, 106001, 0, 6, 80003, 26, "そうね…ほんっとうにね…\n毒まみれのニセドラゴンとか\n恐竜…は逃げられちゃったっけ\nあとワニゴ…ワニの魔物とかね", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (186, 0, 0, 106001, 0, 6, 80003, 27, "そして、とうとう本物の\nドラゴンまで相手に\nしちゃったのよね、あたしたちって", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (187, 0, 0, 106001, 0, 6, 80003, 28, "信じられない強さだったわね\nあのドラゴン…やっぱり\n作戦はしっかり立てていかないと\nダメよね", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (188, 0, 0, 105801, 0, 6, 80003, 19, "えへへ…☆\nキャルちゃんが色んなことを\n覚えていてくれて\nうれしいです♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (189, 0, 0, 105901, 0, 6, 80003, 19, "わたくしも鮮明に覚えておりますよ\n主さまもきっと…♪", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (190, 0, 0, 106001, 0, 6, 80003, 29, "あったり前でしょ！\n忘れないわよ、あんな滅茶苦茶な\nものばかり食べさせられて！\n…忘れられるわけ、ないじゃない", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (191, 0, 0, 106001, 0, 7, 80003, 30, "ねえちょっと、ちょっと待って！？\nカリンから、2.5周年記念の\n生放送に出演してほしいって\n言われたんだけど！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (192, 0, 0, 106001, 0, 7, 80003, 31, "なんでそういう大事なことを\n急に言うわけ！？\nそんなの聞いてないわよ～！？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (193, 0, 0, 106001, 0, 7, 80003, 32, "いっぱい人に見られちゃうのよね？\nなんであたしがそんなこと…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (194, 0, 0, 106001, 0, 7, 80003, 33, "あー\nあー\n…声、これで大丈夫かしら？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (195, 0, 0, 106001, 0, 7, 80003, 34, "聞き取りにくいかもしれないわね…\nもうちょっと明るい方がいいかも\nえっと…こんな感じ？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (196, 0, 0, 106001, 0, 7, 80003, 35, "オイッスー☆", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (197, 0, 0, 106001, 0, 7, 80003, 36, "……\nいや、ないわ\nいつもどおりが一番ね、うん", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (198, 0, 0, 106001, 0, 7, 80003, 37, "もう、記念の生放送なんて\n超責任重大なやつじゃない…\nもしなにか失敗とかしたら…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (199, 0, 0, 106001, 0, 7, 80003, 38, "ど、どど、どうしよう！？\n緊張してきちゃった…！！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (200, 0, 0, 105901, 0, 8, 80003, 20, "主さま、わたくし\nペコリーヌさまとキャルさまと共に\n2.5周年を祝う生放送に\n出演する大役を仰せつかりました", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (201, 0, 0, 105901, 0, 8, 80003, 21, "多くの方々に\n『プリンセスコネクト！\nRe:Dive』の魅力をお伝えする\n重要な役割でございます", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (202, 0, 0, 105901, 0, 8, 80003, 22, "わたくし、全身全霊をもって\n生放送に取り組みたいと\n思っております", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (203, 0, 0, 105901, 0, 8, 80003, 23, "ですが、もしかしたら\nセリフを噛んでしまったり\n段取りを間違えてしまったり\nするかもしれません…", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (204, 0, 0, 105901, 0, 8, 80003, 24, "そのようなことがないよう\n練習はしっかりしておかなくては\nまずはこちらから…", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (205, 0, 0, 105901, 0, 8, 80003, 25, "オイッスー☆", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (206, 0, 0, 105901, 0, 8, 80003, 26, "先ほどキャルさまが練習されて\nいるのをお見かけしたので\nわたくしもと思いまして…\nいかがでしょうか？", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (207, 0, 0, 105901, 0, 8, 80003, 27, "良い感じ、ですか？\n…ふふ、ありがとうございます\n主さまのあたたかいお言葉があれば\nわたくしは百人力でございます", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (208, 0, 0, 105901, 0, 8, 80003, 28, "この大役を無事に成し遂げ\n主さまに素敵な2.5周年を\n迎えていただけるよう…\nわたくし、尽力いたしますね", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (209, 0, 0, 105801, 0, 9, 80003, 20, "オイッスー☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (210, 0, 0, 105801, 0, 9, 80003, 21, "…う～ん、今のはちょっと\n違う感じがしますね\n堅苦しかったかもしれません", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (211, 0, 0, 105801, 0, 9, 80003, 22, "あと６日で2.5周年ですか…", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (212, 0, 0, 105801, 0, 9, 80003, 23, "この年月がオイッスーの\n歴史なんだと思うと\nじ～んとしちゃいます！\nやばいですね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (213, 0, 0, 105801, 0, 9, 80003, 24, "生放送で最高のオイッスー☆　を\nみなさんにお届けするために\n頑張らないと！\nそれじゃあもう一度…", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (214, 0, 0, 105801, 0, 9, 80003, 25, "オイッスー☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (215, 0, 0, 105801, 0, 9, 80003, 26, "…うう～ん、どうしてでしょう\nまだ何かが違う気がします…\nもしかしたら\nおなかが空きすぎてるとか？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (216, 0, 0, 105801, 0, 9, 80003, 27, "今さっき食べたばっかりですけど\nおなかが減っては\n良いオイッスー☆　は\n出せませんよね！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (217, 0, 0, 105801, 0, 9, 80003, 28, "そうと決まれば、コッコロちゃんと\nキャルちゃんを誘って\nごはんにしましょう！\n善は急げです！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (218, 0, 0, 105801, 0, 9, 80003, 29, "あ、二人が丁度いいところに！\nオイッス～☆　…ああ！！\n今の、今のですよ～♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (219, 0, 0, 105801, 0, 9, 80003, 30, "なるほど、どんな時も\n自然体が一番ってことですね！\nこの調子で、生放送も\n頑張っちゃいます♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (220, 0, 0, 105801, 0, 10, 80003, 31, "2.5周年まで残り５日ですが\nその前にもうすぐ生放送ですよ！\nコッコロちゃん\n準備の方はどうですか？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (221, 0, 0, 105901, 0, 10, 80003, 29, "はい。わたくし、しっかりと\n備えてまいりました\n万事抜かりはございません", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (222, 0, 0, 105801, 0, 10, 80003, 32, "おお～すごい自信を感じます…！\nいい生放送になりそうですね☆\n……あれ？　なんだかこの辺り\n揺れていませんか？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (223, 0, 0, 106001, 0, 10, 80003, 39, "…………", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (224, 0, 0, 105901, 0, 10, 80003, 30, "キャルさま？\nお風邪をひかれたんでしょうか\nひどい震えですが…", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (225, 0, 0, 106001, 0, 10, 80003, 40, "かかかか風邪じゃないわよ！\nここここれはただ\nななな生放送が楽しみ過ぎて\nワワワワクワクが止まらないだけ！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (226, 0, 0, 105801, 0, 10, 80003, 33, "大丈夫ですかキャルちゃん！？\nそうだ、これを飲んでください！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (227, 0, 0, 106001, 0, 10, 80003, 41, "きき気がきくじゃない、ありがとっ\nごくっ、んく…ぶはぁっ！？\nちょっと何飲ませたの！？\n辛っ！　苦ぁ！？　甘ぁっ！？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (228, 0, 0, 105801, 0, 10, 80003, 34, "これは魔物のエキスに薬草に\nその他色んなものを混ぜた\n特製の栄養ドリンクです！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (229, 0, 0, 105801, 0, 10, 80003, 35, "これを飲めば体ぽかぽかで\n元気いっぱいですよ♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (230, 0, 0, 106001, 0, 10, 80003, 42, "このアホリーヌ！\n風邪じゃないって言ったでしょ！？\nどさくさに紛れて\nそんな恐ろしいもん飲ませんな～！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (231, 0, 0, 105901, 0, 10, 80003, 31, "キャルさま\n震えが収まっておりますね\nよかったです…\nわたくし、心配いたしました", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (232, 0, 0, 106001, 0, 10, 80003, 43, "え？　ああ、ホントね…って\nだから風邪じゃないって\n言ってるのに…\nまあいいわこの際なんでも", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (233, 0, 0, 105801, 0, 10, 80003, 36, "えっへへ～♪　いつも通りの\nキャルちゃんに戻りましたし\n素敵な生放送が出来そうですね！\n今から楽しみです☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (234, 0, 0, 190801, 0, 11, 80003, 6, "ランドソルのみなさま、こんにちは\n生放送の会場設営を担当しています\n【ギルド管理協会】のカリンです", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (235, 0, 0, 190801, 0, 11, 80003, 7, "【美食殿】のみなさんは\nまもなく始まる生放送に向けて\n最後の調整のため\n席を外しています", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (236, 0, 0, 190801, 0, 11, 80003, 8, "頑張っている３人の\n邪魔をするわけには\nいきませんので、ご容赦ください", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (237, 0, 0, 190801, 0, 11, 80003, 9, "ですので、本日は私から\n【美食殿】のみなさんの様子を\nお伝えさせていただこうと思います", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (238, 0, 0, 190801, 0, 11, 80003, 10, "まずはペコリーヌさんですが…\n何やら大量のおにぎりを\n食べているようです\nえっと…栄養は大事ですよね", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (239, 0, 0, 190801, 0, 11, 80003, 11, "次にコッコロさんですが\nこちらは発声練習をしています", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (240, 0, 0, 190801, 0, 11, 80003, 12, "一生懸命、小さなお口を開けて\n声を出す姿が応援したくなりますね", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (241, 0, 0, 190801, 0, 11, 80003, 13, "そしてキャルさんは…\nこれは…堂々としたものですね\n何もせず、ただ立ち尽くして…", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (242, 0, 0, 190801, 0, 11, 80003, 14, "あれ？\nもしかして緊張で気を失って…？", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (243, 0, 0, 190801, 0, 11, 80003, 15, "…ええと\n【美食殿】のみなさんは\nやる気十分なようですね！", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (244, 0, 0, 190801, 0, 11, 80003, 16, "３人とも生放送を\nいいものにしようと\n全力で頑張ってくれていますので\nどうかご期待ください", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (245, 0, 0, 190801, 0, 11, 80003, 17, "それでは\nまた明日お会いしましょう♪", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (246, 0, 0, 106001, 0, 12, 80003, 44, "2.5周年まであと３日！\nそして生放送は明日！\nなんかいよいよって感じね…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (247, 0, 0, 105801, 0, 12, 80003, 37, "３人でい～っぱい練習しましたし\nきっと大丈夫ですよ☆", "ペコリーヌ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (248, 0, 0, 105901, 0, 12, 80003, 32, "ペコリーヌさまに\n大丈夫と言ってもらえると\nとても心強いですね", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (249, 0, 0, 106001, 0, 12, 80003, 45, "信じすぎちゃだめよコロ助\nこいつはなーんにも\n考えてないだけなんだから", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (250, 0, 0, 105801, 0, 12, 80003, 38, "ひどいですよぉキャルちゃ～ん！", "ペコリーヌ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (251, 0, 0, 105901, 0, 12, 80003, 33, "ふふ。お二人とも\n普段通りの様子で\n安心いたしました", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (252, 0, 0, 105801, 0, 12, 80003, 39, "はいっ☆\n生放送でもなんでも\n全力全開、わたしらしく\nぶつかっていくだけです！", "ペコリーヌ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (253, 0, 0, 106001, 0, 12, 80003, 46, "そうね。おめでたいことなんだし\nここまで来たんなら\n楽しめるだけ\n楽しむしかないわよね！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (254, 0, 0, 105901, 0, 12, 80003, 34, "わたくしも、普段よりも心が\n熱くなっております\nこの胸の気持ちをお伝えできるよう\n精一杯努力いたします…！", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (255, 0, 0, 105801, 0, 12, 80003, 40, "それでは、いきましょう！\n明日の生放送、絶対に\n成功させましょうね☆", "ペコリーヌ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (256, 0, 0, 105801, 0, 13, 80003, 41, "えっと、最初のひと言は…あれ？\nキャルちゃん、わたし\n何て言うんでしたっけ？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (257, 0, 0, 106001, 0, 13, 80003, 47, "は！？\nなにいきなりど忘れしてるの！？\nっていうかあんた、台本は！？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (258, 0, 0, 105801, 0, 13, 80003, 42, "忘れてきちゃいました☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (259, 0, 0, 106001, 0, 13, 80003, 48, "忘れてきちゃいました☆\nで済ませられると思ってんの！？\nほら、あたし二冊持ってきたから\nこれ使いなさい！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (260, 0, 0, 105901, 0, 13, 80003, 35, "マイクとは、こんな高い位置に\nあるものなのですね…！\n背伸びをすれば、何とか…\nう～ん、うぅ～ん…！", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (261, 0, 0, 106001, 0, 13, 80003, 49, "あぁもう\n少し下げればいいでしょ！？\nこれくらいでいい？\nまったく、世話が焼けるわね…", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (262, 0, 0, 105801, 0, 13, 80003, 43, "あれ？\nキャルちゃん、後ろ髪が\nはねちゃってますよ？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (263, 0, 0, 106001, 0, 13, 80003, 50, "え？　うそっ！？\nちゃんと確かめてきたのに！\nどこどこ！？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (264, 0, 0, 105901, 0, 13, 80003, 36, "キャルさま、動かないで\nくださいまし。今くしで…\nはい、直りましたよ", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (265, 0, 0, 106001, 0, 13, 80003, 51, "あ、ありがと…はぁ。生放送\n本番までもうすぐなのに\nこんなことしてる場合じゃ\nないわよね", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (266, 0, 0, 105901, 0, 13, 80003, 37, "はい、時間は残りわずかです\nですが、慌ただしく\n動き回るこの時間も\nなんだか楽しくて…♪", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (267, 0, 0, 106001, 0, 13, 80003, 52, "コロ助、あんた…って\nそうじゃなくて！\n胸にジンワリきてる\n暇なんかないでしょ…！？", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (268, 0, 0, 105801, 0, 13, 80003, 44, "あはは♪\nキャルちゃんの動きが\nとっても面白いです♪\nやばいですね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (269, 0, 0, 105901, 0, 13, 80003, 38, "ふふ\nきっと面白い生放送になると\nわたくし、確信しております", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (270, 0, 0, 105801, 0, 13, 80003, 45, "絶対絶対、間違いありません！\n見てくれるみなさんが\n笑顔になれる時間を\nお届けしましょう！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (271, 0, 0, 106001, 0, 13, 80003, 53, "そんなの当然でしょ！\n誰が見たって面白いって\n言ってもらえるように\nあれだけ準備したんだから！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (272, 0, 0, 105801, 0, 13, 80003, 46, "それでは\n記念日直前生放送！\n楽しみにしててくださいね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (273, 0, 0, 190801, 0, 14, 80003, 18, "こんにちは\n【ギルド管理協会】のカリンです", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (274, 0, 0, 190801, 0, 14, 80003, 19, "昨日の生放送は\nいかがだったでしょうか？", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (275, 0, 0, 190801, 0, 14, 80003, 20, "たくさんの笑顔と喜びと\nそして驚きを受け取って\nいただけたのではないかと思います", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (276, 0, 0, 190801, 0, 14, 80003, 21, "そしていよいよ\n明日は2.5周年の当日\n待ちに待った記念日を\n迎えることとなります", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (277, 0, 0, 190801, 0, 14, 80003, 22, "【美食殿】のみなさんも\n張り切って様々な準備を\nされていますよ", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (278, 0, 0, 190801, 0, 14, 80003, 23, "【ギルド管理協会】も\n万全のサポート体制で\n協力してまいりたいと思います", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (279, 0, 0, 190801, 0, 14, 80003, 24, "…ふふ、本当に楽しみですね\n【ギルド管理協会】の職員として\nだけではなく、私個人としても…", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (280, 0, 0, 190801, 0, 14, 80003, 25, "この記念日を迎えられることが\n心から楽しみですし\n幸せを感じています", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (281, 0, 0, 190801, 0, 14, 80003, 26, "きっと【美食殿】のみなさんは\nそれ以上に心を弾ませて\nいることでしょう", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (282, 0, 0, 190801, 0, 14, 80003, 27, "それでは\n明日からの2.5周年を\nどうぞ、お楽しみに…♪", "カリン", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (283, 0, 0, 105801, 0, 15, 80003, 47, "準備はいいですかっ？\n…いっきますよー！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (284, 0, 0, 106001, 0, 15, 80003, 54, "祝！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (285, 0, 0, 105901, 0, 15, 80003, 39, "2.5周年！", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (286, 0, 0, 105801, 0, 15, 80003, 48, "おめでとうございま～す☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (287, 0, 0, 106001, 0, 15, 80003, 55, "少し前まではまだまだ先じゃない\nとか言ってたけど\n本当にあっという間だったわね", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (288, 0, 0, 105901, 0, 15, 80003, 40, "光陰矢の如し…\nとはこのことでございますね\nでも、今日という日を無事に\n迎えることができて良かったです", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (289, 0, 0, 105801, 0, 15, 80003, 49, "コッコロちゃん！　キャルちゃん！\n落ち着くには\nまだ早いですよ！\n盛り上がるのはこれからです☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (290, 0, 0, 106001, 0, 15, 80003, 56, "ほんとあんたはいつも\n全力全開ねー\nでもそうね、記念日なんだし\nパーっといきましょ！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (291, 0, 0, 105901, 0, 15, 80003, 41, "ええ、わたくしも全力全開で\nまいります…！\n主さま、さあ\nどうぞ手を取ってくださいまし…♪", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (292, 0, 0, 106001, 0, 15, 80003, 57, "あんたもコロ助も、浮かれて\n転ぶんじゃないわよ？\n…仕方ないから、あたしも\n手を繋いであげるわよ", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (293, 0, 0, 105801, 0, 15, 80003, 50, "あー！　二人ともずるいです！\nわたしもっ、ギュー♪", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (294, 0, 0, 106001, 0, 15, 80003, 58, "ちょっ、ペコリーヌ！\nくっつき過ぎよ！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (295, 0, 0, 105801, 0, 15, 80003, 51, "記念日だから\n平気平気♪\nやばいですね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (296, 0, 0, 106001, 0, 15, 80003, 59, "意味分かんないわよ！", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (297, 0, 0, 105901, 0, 15, 80003, 42, "ふふ。このめでたき日に\n喜びがあふれておりますね\n主さまは…いかがでしょうか？", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (298, 0, 0, 105901, 0, 15, 80003, 43, "喜んでいただけているならば\nわたくしはとてもとても\n幸せでございます", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (299, 0, 0, 105801, 0, 15, 80003, 52, "さぁ、2.5周年を\n楽しみ尽くしますよ☆\nまだまだ食べたいものもありますし\nやりたいこともたくさんです！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (300, 0, 0, 106001, 0, 15, 80003, 60, "分かった、分かったから\n引っ張るんじゃないわよ！\n…そんな掴まなくても\nちゃんとついていくから", "キャル", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (301, 0, 0, 105901, 0, 15, 80003, 44, "ペコリーヌさま…キャルさま…\n主さま…共にまいりましょう\nどこまでも…！", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (302, 0, 0, 105801, 0, 15, 80003, 53, "はい！　それでは2.5周年\n食べつくしツアーへ！\nそして、その先の未来へ\n向かって出発しましょう！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (303, 0, 1, 105801, 0, 15, 80003, 54, "2.5周年\nありがとうございます！", "ペコリーヌ・コッコロ・キャル", 0, "105901,45,106001,61");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (304, 0, 0, 190804, 1, 0, 60002, 1, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (305, 1, 0, 0, 1, 0, 60002, 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (306, 1, 0, 0, 1, 0, 60002, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (307, 1, 0, 0, 1, 0, 60002, 0, "今日の運勢は姫吉！　最強の運勢でどんなドジも跳ね除けます！　大切な人と一緒に、最高の一日になること間違いなし！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (308, 1, 0, 0, 1, 0, 60002, 0, "今日の運勢は姫吉！　どんな挑戦も上手くいく、最高の運勢です！理想の自分に変身できる絶好の機会！　新しい一歩を踏み出そう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (309, 1, 0, 0, 2, 0, 60002, 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (310, 2, 0, 0, 1, 0, 60002, 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (311, 2, 0, 0, 1, 0, 60002, 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (312, 2, 0, 0, 1, 0, 60002, 0, "今日の運勢は大吉！　ラッキーワードは「ちぇる～ん♪」　　　　出会う人みんなに言ってあげると、ハッピーになれますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (313, 2, 0, 0, 1, 0, 60002, 0, "今日の運勢は大吉！　運勢はバッチリで無敵状態！　　　　　　　龍眼で全てを見通して、思い通りの一日を過ごしましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (314, 2, 0, 0, 2, 0, 60002, 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (315, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (316, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (317, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (318, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (319, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　商売運が上がってきています！　　　　　　ラッキーアイテムはたい焼き！　和菓子パワーで売上アップです！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (320, 3, 0, 0, 1, 0, 60002, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (321, 3, 0, 0, 2, 0, 60002, 0, "今日の運勢は中吉！　運気が着々と上昇中！　　　　　　　　　　精霊の加護を受けたかのごとく、色々な事がうまくいきますよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (322, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (323, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (324, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (325, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　運気は高いけども、ハプニングには注意！　出かけた先で、「ふしんしゃ」扱いされてしまうかも……", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (326, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (327, 4, 0, 0, 1, 0, 60002, 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (328, 4, 0, 0, 2, 0, 60002, 0, "今日の運勢は小吉！　根を詰めずにリラックスすると運気向上！　ラッキーパーソンはアイドル。歌があなたを幸せにしてくれます♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (329, 0, 0, 190804, 0, 0, 60002, 2, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", "カリン", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (330, 0, 0, 190804, 0, 7, 60002, 3, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", "カリン", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (331, 0, 0, 105901, 0, 1, 80005, 1, "ささ、シェフィさまはこちらへ…", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (332, 0, 0, 106401, 0, 1, 80005, 1, "コッコロさん、どこへ行くの…？\n…え？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (333, 0, 0, 105801, 0, 1, 80005, 1, "『おめでとうございます！\nわ～パチパチー！』\n…という感じでどうですかね！？", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (334, 0, 0, 105901, 0, 1, 80005, 2, "ではわたくしも\n後ろからクラッカーを鳴らして\n応戦いたします\nああ、当日が待ち遠しいですね", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (335, 0, 0, 106401, 0, 1, 80005, 2, "ええと…\n二人とも何をしているの？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (336, 0, 0, 106001, 0, 1, 80005, 1, "シェフィは初めてだもんね\nあの日が近いからって\n予行練習してんのよ\n気が早いわよね～", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (337, 0, 0, 106401, 0, 1, 80005, 3, "あの日…？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (338, 0, 0, 105801, 0, 1, 80005, 2, "その通りです…\nいよいよ記念すべきあの日が\n近づいてきましたよ！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (339, 0, 0, 105801, 0, 1, 80005, 3, "『プリンセスコネクト！\nRe:Dive』3.5周年！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (340, 0, 0, 190801, 0, 1, 80005, 1, "やばいですね☆", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (341, 0, 0, 106001, 0, 1, 80005, 2, "って、なにしれっと\n参加してんのよカリン！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (342, 0, 0, 190801, 0, 1, 80005, 2, "ふふ、いいじゃないですか\n【ギルド管理協会】として\n私もみなさんと一緒に\nお祝いをさせてください！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (343, 0, 0, 190801, 0, 1, 80005, 3, "それに…記念日が近づけば\nとっておきの情報を\nお届けしますから♪", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (344, 0, 0, 105801, 0, 1, 80005, 4, "というわけで\n今日からシェフィちゃんも一緒に\nカウントダウンしちゃいましょう！\n3.5周年まで…", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (345, 0, 0, 106401, 0, 1, 80005, 4, "えっ！？　ええとええと…！\nあ、あと14日…！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (346, 0, 0, 105801, 0, 2, 80005, 5, "3.5周年まであと13日\n豪華に、そして盛大に\nお祝いしたいですね☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (347, 0, 0, 105901, 0, 2, 80005, 3, "豪華といえば前にとある貴族さまが\n舞踏会を開かれたそうで\n主さまがそのお手伝いを\nしておりました", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (348, 0, 0, 105901, 0, 2, 80005, 4, "そこで美しい所作を学ばれたので\nわたくしも教えていただきました\nしゃなり、しゃなり…\nいかがでしょう？", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (349, 0, 0, 105801, 0, 2, 80005, 6, "すっごく上手ですよ☆\nまるでお姫様みたいです\nせっかくなのでわたしも\nしゃなりしゃなり", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (350, 0, 0, 105901, 0, 2, 80005, 5, "さすがでございます\nペコリーヌさま", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (351, 0, 0, 106001, 0, 2, 80005, 3, "いや、あんたは\nできなきゃダメでしょ\n本物のお姫様なんだし", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (352, 0, 0, 106401, 0, 2, 80005, 5, "しゃなり、しゃなり…\nふふ、案外できるものね", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (353, 0, 0, 105801, 0, 2, 80005, 7, "わぁ！\nシェフィちゃん\n姿勢がとってもキレイです♪", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (354, 0, 0, 105901, 0, 2, 80005, 6, "さ、次はキャルさまの\n番でございますよ", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (355, 0, 0, 106001, 0, 2, 80005, 4, "あ、あたしはいいわよ！\nそういうの全然分かんないし…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (356, 0, 0, 106401, 0, 2, 80005, 6, "大丈夫\nやってみると結構楽しいわよ\nほらほらっ", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (357, 0, 0, 106001, 0, 2, 80005, 5, "そ、そこまで言うなら…\nしゃなにゅわきゃあっ！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (358, 0, 0, 106001, 0, 2, 80005, 6, "いたたた…もぉお～！\nなんであたしがこんな目に～！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (359, 0, 0, 105901, 0, 2, 80005, 7, "まぁまぁ\n記念日までに練習すれば\nできるようになるかもしれません\nよろしければお教えいたしますよ", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (360, 0, 0, 106001, 0, 2, 80005, 7, "よし！\nあんたたちができて\nあたしだけできないのはしゃくだし\nやってやろうじゃないの！！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (361, 0, 0, 105901, 0, 3, 80005, 8, "3.5周年まであと12日\n記念日当日はもちろんですが\nその日を待つ時間というのも\n心躍ります", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (362, 0, 0, 105801, 0, 3, 80005, 8, "分かりますっ！\nどんな特別な料理を食べられるのか\n考えるだけでワクワクしますよね！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (363, 0, 0, 105901, 0, 3, 80005, 9, "特別な料理といえば、お祭りですね\nそういえば主さまは学生として\n聖学祭に参加されたこと\nがあるとか…", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (364, 0, 0, 106401, 0, 3, 80005, 7, "聖学祭…って、なにかしら？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (365, 0, 0, 105901, 0, 3, 80005, 10, "聖テレサ女学院の祭典ですよ\n二つのチームが競い合い\n青春を満喫するのが趣旨のようです", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (366, 0, 0, 106001, 0, 3, 80005, 8, "それってカルミナの\nサプライズライブがあった\nお祭りよね？\nちょっと見たかったかも…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (367, 0, 0, 106001, 0, 3, 80005, 9, "カルミナの後の\nライブも好評だったらしいじゃない\n確か、なかよし部\nだったっけ…？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (368, 0, 0, 105801, 0, 3, 80005, 9, "なかよし部…\n仲が良さそうな名前で\nやばいですね☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (369, 0, 0, 106001, 0, 3, 80005, 10, "いや、そのまんますぎでしょ…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (370, 0, 0, 106401, 0, 3, 80005, 8, "聖学祭かぁ…なんだか楽しそうね\nそれになかよし部の人たちも\n気になるわ", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (371, 0, 0, 105801, 0, 3, 80005, 10, "それじゃあわたしたちも、\n負けじと仲良くしましょう♪\nほらほらシェフィちゃん、\nぎゅーっ☆　ですよ♪", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (372, 0, 0, 106401, 0, 3, 80005, 9, "えっ？　ええ…\nぎゅーっ…？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (373, 0, 0, 106001, 0, 4, 80005, 11, "3.5周年まであと11日！？\nお祝いの準備進んでないんだけど…\nああ～昨日に戻りたいわ…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (374, 0, 0, 106401, 0, 4, 80005, 10, "そういえばそんな魔道具があるって\n聞いたことがあるわね\n確か、名前はタイムラーベ…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (375, 0, 0, 106001, 0, 4, 80005, 12, "なにそれヤバいわね\nでも本当にあるんだったら\n準備よりももっとやり直したいこと\nたくさんあるんだけど…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (376, 0, 0, 105901, 0, 4, 80005, 11, "もしや正月の件でしょうか…？\nあの時はお金がなくて\n苦労しましたから", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (377, 0, 0, 106001, 0, 4, 80005, 13, "あれはそうね…\nお金を湯水のように使う\nぺコリーヌを止められたら\nあんな苦労をすることもなかったし", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (378, 0, 0, 105801, 0, 4, 80005, 11, "そんなこともありましたね！\nやり直したいといえば\n『きゃるきゃる～ん♪』\nの方かと思いましたよ！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (379, 0, 0, 106001, 0, 4, 80005, 14, "バラすんじゃないわよ\nこのアホリーヌ！\nシェフィはそれ\n知らないんだから！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (380, 0, 0, 106001, 0, 4, 80005, 15, "こうなったらもう、なんとか\nタイムラーべを探し出して\n今の会話をなかったことに…\nって、どうしたのよシェフィ", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (381, 0, 0, 106401, 0, 4, 80005, 11, "うん…もし、私だったら…\n私が知らないみんなとの時間を\n見てみたいな、って…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (382, 0, 0, 105801, 0, 4, 80005, 12, "シェフィちゃん！　タイムなんとか\nなんかなくても大丈夫ですよ！\n一緒の時間はこれから\nどんどん作ればいいんですから！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (383, 0, 0, 105901, 0, 4, 80005, 12, "はい、今この瞬間も\n未来にはかけがえのない思い出に\nなっていることでしょう", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (384, 0, 0, 106001, 0, 4, 80005, 16, "だからそんな顔しないの\nほら、お祝いの準備、進めるわよ！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (385, 0, 0, 106401, 0, 4, 80005, 12, "みんな…そうね\n最高のお祝いにして\n最高の思い出にしましょう！", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (386, 0, 0, 105801, 0, 5, 80005, 13, "3.5周年まで、あと10日！\nもうすぐですよー！\n楽しみすぎて、やばいですね！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (387, 0, 0, 105801, 0, 5, 80005, 14, "そういえば…たくさんのおもちゃが\n子どもたちを襲うっていう\n騒動もありましたね…\nなんでも勝手に動き出したとか！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (388, 0, 0, 105801, 0, 5, 80005, 15, "学校や孤児院とかに\nちっちゃなおもちゃが乗り込んで\n暴れたみたいですよ！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (389, 0, 0, 106001, 0, 5, 80005, 17, "暴れたって言っても\n所詮はおもちゃじゃない\nどうせちっさいんでしょ？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (390, 0, 0, 106001, 0, 5, 80005, 18, "だったら魔法で\n全部ぶっ飛ばせばいいじゃない！\n大したことないわよ！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (391, 0, 0, 106401, 0, 5, 80005, 13, "キャルってば…\n相手は子どもが\n大事にしてる物なのよ…？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (392, 0, 0, 105901, 0, 5, 80005, 13, "乱暴な発言は\nめっ、でございますよ？\n子どもの教育に悪影響を\n与えてしまいますから…", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (393, 0, 0, 105801, 0, 5, 80005, 16, "キャルちゃんだって\n意外と猫グッズとか\nたっくさん集めてますよね？\nもしその子たちが暴れたら…？", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (394, 0, 0, 106001, 0, 5, 80005, 19, "う、うっさいわね！\n意外とか言うな！\n…ま、まあ確かに正面切って\n魔法でぶっ飛ばせないかもね…", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (395, 0, 0, 105801, 0, 5, 80005, 17, "あはは☆\nキャルちゃんのそういうところ\n好きですよ♪", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (396, 0, 0, 105801, 0, 5, 80005, 18, "そんなキャルちゃんに猫グッズを\nプレゼントしちゃいますね！\n一部で流行っていた、たい焼き屋の\nおまけフィギュアですよ♪", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (397, 0, 0, 105801, 0, 5, 80005, 19, "乱暴に扱ったりしないでくださいね\nひとりでに暴れ出しちゃうかも\nしれませんから！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (398, 0, 0, 190801, 0, 6, 80005, 4, "3.5周年まであと９日\nここでみなさんに\nビックニュースですよ！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (399, 0, 0, 190801, 0, 6, 80005, 5, "3.5周年を祝う生放送に\n去年と同様【美食殿】の\nみなさんにご出演いただくことが\n決定しましたー！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (400, 0, 0, 106001, 0, 6, 80005, 20, "…えっ！？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (401, 0, 0, 105801, 0, 6, 80005, 20, "本当ですか！？\nそれじゃ今から張り切って\n生放送中に食べる魔物料理を\n作らなくちゃですね☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (402, 0, 0, 106401, 0, 6, 80005, 14, "いや…がんばるところは\nそこじゃないような…\nというか去年も出演してたのね\nすごいじゃない！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (403, 0, 0, 105901, 0, 6, 80005, 14, "はい。とても緊張しますが\nやりがいのある大役です\n一緒にがんばりましょうね\nシェフィさま", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (404, 0, 0, 106401, 0, 6, 80005, 15, "わ、私も出るの！？　でも…\n私も【美食殿】の一人だものね\nそれなら今からしっかり準備をして\nコンディションを整えないと…", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (405, 0, 0, 106001, 0, 6, 80005, 21, "ふふん♪\n生放送直前のカチコチになった\nシェフィの姿が楽しみだわ！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (406, 0, 0, 105801, 0, 6, 80005, 21, "去年のキャルちゃんは\n緊張しすぎてずっと震えて\nかわいかったですもんね！\n今年もあの姿が見たいです！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (407, 0, 0, 106001, 0, 6, 80005, 22, "ぶっ殺すぞ！？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (408, 0, 0, 190801, 0, 6, 80005, 6, "というわけで\n『プリンセスコネクト！\nRe:Dive』の魅力を\nお伝えする生放送をお楽しみに♪", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (409, 0, 0, 105901, 0, 7, 80005, 15, "3.5周年まであと８日\nでございますよ\n楽しみですね、主さま", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (410, 0, 0, 106001, 0, 7, 80005, 23, "そういえばあんた\n夏休みの宿題は\nきちんとやってるの？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (411, 0, 0, 106401, 0, 7, 80005, 16, "宿題…学校に通うのも\n楽しいことばかりじゃ\nないのね", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (412, 0, 0, 105801, 0, 7, 80005, 22, "あれ？　そういえば\n少し前にルーセント学院で\n何かあったような…", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (413, 0, 0, 106001, 0, 7, 80005, 24, "ああ、始業式の日に\n大捕り物があったって\n話題になってたわね", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (414, 0, 0, 106401, 0, 7, 80005, 17, "夏休みを終わらせないって\n騒いでたっていう話？\nあれ本当なの？\n都市伝説だと思ってたわ", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (415, 0, 0, 105901, 0, 7, 80005, 16, "その一件ならよく存じ上げて\nおります。ですから主さま\n次の機会にはわたくしと一緒に\nがんばりましょう", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (416, 0, 0, 106401, 0, 7, 80005, 18, "楽しそう…私も一緒にやりたいな\nママ…じゃ、じゃなくて！\nコッコロさん、私もまざっていい？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (417, 0, 0, 105901, 0, 7, 80005, 17, "もちろんでございます\n仲良くお勉強いたしましょう", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (418, 0, 0, 106001, 0, 7, 80005, 25, "しれっと教育ママが\n生まれてる…？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (419, 0, 0, 105801, 0, 7, 80005, 23, "お勉強は大切ですよ！\nキャルちゃんも一緒に\nがんばりましょう！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (420, 0, 0, 106001, 0, 7, 80005, 26, "え～～～～！？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (421, 0, 0, 106001, 0, 8, 80005, 27, "3.5周年まであと７日〜♪\nふふ～ん♪\nふんふふ～ん♪", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (422, 0, 0, 106401, 0, 8, 80005, 19, "…\nねぇコッコロさん\nキャル、どうしちゃったの？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (423, 0, 0, 105901, 0, 8, 80005, 18, "とてもご機嫌そうに\n鼻歌を歌ってらっしゃいますね\n耳も尻尾もリズミカルに\n揺れて…ノリノリでございます", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (424, 0, 0, 105801, 0, 8, 80005, 24, "あれはですね！\nカルミナのみなさんの\nサマーライブのチケットが\n手に入ったからなんですよ♪", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (425, 0, 0, 106401, 0, 8, 80005, 20, "ええっ！？\nあのライブのチケットって確か\n入手困難だったんじゃ…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (426, 0, 0, 106001, 0, 8, 80005, 28, "ふふふふ～ん♪\nしゃいにんぐふゅ～ちゃ～♪", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (427, 0, 0, 105901, 0, 8, 80005, 19, "なるほど…\nキャルさまがあのように\nなってしまうのも頷けますね", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (428, 0, 0, 106401, 0, 8, 80005, 21, "…カルミナの\n『Shining Future』\nの中に、シャイニングフューチャー\nって歌詞はなかったはずだけど…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (429, 0, 0, 106001, 0, 8, 80005, 29, "ふんふ…はっ！？\nあっ、あんたたち！\nなに人の鼻歌を\n勝手に聞いてるのよ！？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (430, 0, 0, 106001, 0, 8, 80005, 30, "こっ、これは別に\nカルミナの曲じゃなくて…\nあたしのオリジナルソングよ！\n聞いたらお金取るわよっ！？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (431, 0, 0, 105801, 0, 8, 80005, 25, "えへへ、キャルちゃん\nカルミナのサマーライブ\n思いっきり楽しみましょうね☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (432, 0, 0, 106001, 0, 8, 80005, 31, "も～っ！\n生暖かい目で見るな～～！\nぶっ殺すわよ～～～！", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (433, 0, 0, 106401, 0, 9, 80005, 22, "3.5周年まであと６日\n３人も言ってたけど\nあっという間だったわね", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (434, 0, 0, 106401, 0, 9, 80005, 23, "…えっ？\n生放送の意気込み！？\n突然なに！？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (435, 0, 0, 106401, 0, 9, 80005, 24, "ええと…\nとにかく失敗しないように\n台本たくさん読んで…\nそれから…", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (436, 0, 0, 106401, 0, 9, 80005, 25, "えっ！？\nトラブルがあったら\nどうするのかって！？\nそ、それは…！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (437, 0, 0, 106401, 0, 9, 80005, 26, "とにかく落ち着いて\nスタッフさんの指示を聞いて…", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (438, 0, 0, 106401, 0, 9, 80005, 27, "それから、それから…！\nぅ、ぅぅっ…！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (439, 0, 0, 106401, 0, 9, 80005, 28, "―びえぇぇ～んっ！！！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (440, 0, 0, 105901, 0, 9, 80005, 20, "どうされましたか、シェフィさま", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (441, 0, 0, 106401, 0, 9, 80005, 29, "ううっ…ひっく…\nママッ…！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (442, 0, 0, 105901, 0, 9, 80005, 21, "よしよし、緊張されてるのですね\nママが傍におりますよ\n主さま、少々お待ちくださいませ", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (443, 0, 0, 105901, 0, 9, 80005, 22, "…ふぅ\nシェフィさま\n生放送への意気込み\nお話しできそうですか？", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (444, 0, 0, 106401, 0, 9, 80005, 30, "…ううっ\n恥ずかしすぎて\nもう生放送出られない…", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (445, 0, 0, 105901, 0, 10, 80005, 23, "主さま\n3.5周年まであと５日\nでございます", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (446, 0, 0, 105901, 0, 10, 80005, 24, "ですがその前に\n生放送がありますね", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (447, 0, 0, 105901, 0, 10, 80005, 25, "…生放送に向けた\n意気込みでございますか？", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (448, 0, 0, 105901, 0, 10, 80005, 26, "もちろんわたくしは\n主さまのために\n全身全霊を込めて\n楽しい時間をご提供いたします", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (449, 0, 0, 105901, 0, 10, 80005, 27, "…と、意気込んでみましたが\nうまくできるか少し不安です\n声が小さくなったり\n間違えてしまったらどうしようと…", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (450, 0, 0, 105901, 0, 10, 80005, 28, "ですがわたくしは\n一人ではありません\n【美食殿】のみなさまが\nおります", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (451, 0, 0, 105901, 0, 10, 80005, 29, "どんな困難も\nみなさまと一緒なら\n乗り越えられると\nわたくし、確信しております", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (452, 0, 0, 105901, 0, 10, 80005, 30, "それに今回はシェフィさまも\nご参加されるわけですし\nママとしてお手本に\nならねばなりませんね", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (453, 0, 0, 105901, 0, 10, 80005, 31, "主さま。3.5周年も\n食卓を囲んでいる時のような\n楽しい思い出を\n一緒に作りましょうね", "コッコロ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (454, 0, 0, 105801, 0, 11, 80005, 26, "3.5周年まであと４日！\nやばいですね☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (455, 0, 0, 106001, 0, 11, 80005, 32, "はいはい、やばいわね\nというかもうすぐ生放送だけど\nあんた準備はできてるの？", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (456, 0, 0, 105801, 0, 11, 80005, 27, "ばっちりオイッスー☆　ですよ！\n『王家の装備』も全開です！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (457, 0, 0, 105801, 0, 11, 80005, 28, "あとは前回を超える\n最高のオイッスー☆　を\nお届けできるように\n練習あるのみですかね！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (458, 0, 0, 105801, 0, 11, 80005, 29, "キャルちゃんは\nどうなんですか？\nオイッスー☆　を\n毎日ちゃんと練習してますか？", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (459, 0, 0, 106001, 0, 11, 80005, 33, "はぁ！？　なんであたしまで\nその変なあいさつを練習しないと\nいけないのよ！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (460, 0, 0, 105801, 0, 11, 80005, 30, "もしかしてやってないんですか？\nダメですよキャルちゃん！\nシェフィちゃんだってちゃんと\n毎日練習してるのに！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (461, 0, 0, 105801, 0, 11, 80005, 31, "こうなったらわたしがキャルちゃん\nにオイッスー☆　の『オ』から\nしっかり教えてあげないと！", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (462, 0, 0, 105801, 0, 11, 80005, 32, "オイッスー☆　の『オ』は\n口を大きく開いて〜\nドラゴンの骨つき肉に\nかぶりつく直前をイメージして〜", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (463, 0, 0, 106001, 0, 11, 80005, 34, "だからあたしはやるなんて一言も…", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (464, 0, 0, 105801, 0, 11, 80005, 33, "オイッスー☆", "ペコリーヌ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (465, 0, 0, 106001, 0, 11, 80005, 35, "聞きなさいっての！！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (466, 0, 0, 106401, 0, 12, 80005, 31, "3.5周年まであと３日…\nそして生放送は、明日…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (467, 0, 0, 106401, 0, 12, 80005, 32, "もっと台本を\n読み込んでおかないと…\nあと発声練習も…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (468, 0, 0, 106401, 0, 12, 80005, 33, "おいっす！\n…こうじゃなかったわね\nええと確か…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (469, 0, 0, 106401, 0, 12, 80005, 34, "うう…あんなに練習したのに\nこれじゃみんなに迷惑かけちゃう…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (470, 0, 0, 106401, 0, 12, 80005, 35, "【美食殿】の一員として\n認められるように\n頑張らないといけないのに\nよし、もう一度…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (471, 0, 0, 105801, 0, 12, 80005, 34, "やってますねシェフィちゃん！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (472, 0, 0, 106001, 0, 12, 80005, 36, "なによ、考えることは\nみんな同じってこと？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (473, 0, 0, 105901, 0, 12, 80005, 32, "ふふ。シェフィさま\nよろしければ\n仲間に入れてください\n一緒にやればきっとうまくできます", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (474, 0, 0, 106401, 0, 12, 80005, 36, "みんな…もちろんよ！", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (475, 0, 0, 105801, 0, 12, 80005, 35, "それじゃ明日の生放送に向けて\n一緒に練習がんばりましょう☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (476, 0, 0, 190801, 0, 13, 80005, 7, "3.5周年まであと２日と\n迫った本日は…\nいよいよ生放送です！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (477, 0, 0, 190801, 0, 13, 80005, 8, "【美食殿】のみなさんが\n準備に入られていますので\nそれぞれ繋いでみましょう！\nまずはペコリーヌさんです！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (478, 0, 0, 105801, 0, 13, 80005, 36, "今日もオイッスー☆\nみんなで一緒に\nオイッスー☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (479, 0, 0, 190801, 0, 13, 80005, 9, "お手本になるような\n発声練習ですね！\nそれでは続いてコッコロさん", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (480, 0, 0, 105901, 0, 13, 80005, 33, "はじめちょろちょろ\nなかぱっぱ～♪\n生放送前にみなさまで\n食卓を囲んで英気を養いましょう", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (481, 0, 0, 190801, 0, 13, 80005, 10, "さすが【美食殿】のママですね！\nそしてキャルさんは…", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (482, 0, 0, 106001, 0, 13, 80005, 37, "大丈夫…大丈夫…\nあたしは大丈夫…", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (483, 0, 0, 190801, 0, 13, 80005, 11, "す、すごく震えてますけど\n大丈夫でしょうか…？\nそして今回初参加となる\n期待の新人シェフィさん！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (484, 0, 0, 106401, 0, 13, 80005, 37, "あうー？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (485, 0, 1, 105801, 0, 13, 80005, 37, "あ…", "みんな", 4, "105901,34,106001,38,190801,12");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (486, 0, 0, 106001, 0, 13, 80005, 39, "ちょ、ちょっとシェフィ！？\nなに赤ちゃん返りしてん―\nあ痛ぁっ！\n噛んだわこいつーっ！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (487, 0, 0, 105901, 0, 13, 80005, 35, "シェフィさま\n緊張しすぎて\nしまったのでしょうね…\nおーよしよし…", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (488, 0, 0, 105801, 0, 13, 80005, 38, "シェフィちゃん！\nそういう時は手のひらに\n好きな文字を書いて\n食べちゃうといいですよ！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (489, 0, 0, 190801, 0, 13, 80005, 13, "…ええと、現場からは以上です！\n生放送はもうすぐ！\n特別なお知らせもありますので\nどうぞお楽しみに！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (490, 0, 0, 106401, 0, 14, 80005, 38, "3.5周年の記念日も\nいよいよ明日ね\n…って、あれ？", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (491, 0, 0, 105801, 0, 14, 80005, 39, "記念日はこの森へ行きませんか！？\nすっごく美味しいお肉が\nとれるんです☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (492, 0, 0, 106001, 0, 14, 80005, 40, "うげ、またあの魔物？\nさすがに今度は\n丸焼きとかはやめてよね…\n見た目がヤバすぎるし", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (493, 0, 0, 105901, 0, 14, 80005, 36, "ふふ、キャルさまもだいぶ\n魔物肉に慣れてきたようですね\n調理ならばわたくしに\nお任せください♪", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (494, 0, 0, 106401, 0, 14, 80005, 39, "みんな、何をしているの？\nなんだか、\n不穏な単語が聞こえたんだけど…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (495, 0, 0, 105801, 0, 14, 80005, 40, "シェフィちゃん！\n明日の食べ尽くしツアーの\n相談をしてたんですよ！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (496, 0, 0, 105901, 0, 14, 80005, 37, "はい。明日は【美食殿】の\n一員となったシェフィさまと一緒に\n初めて記念日を過ごすのですから\n特別なコース料理を用意しませんと", "コッコロ", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (497, 0, 0, 106001, 0, 14, 80005, 41, "ふふん♪\n猫の毛も逆立つような\nあれこれを食べさせられるから\n覚悟しておいたほうがいいわよ？", "キャル", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (498, 0, 0, 106401, 0, 14, 80005, 40, "へ、へぇ…", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (499, 0, 0, 105801, 0, 14, 80005, 41, "期待しててくださいね！\nシェフィちゃんとあなたに\n『おいちー！』って喜んでもらえる\n最高のごちそうを準備しますから☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (500, 0, 0, 106401, 0, 14, 80005, 41, "ええと…その…うーんと…\nわ、分かったわ\n私も【美食殿】の一員だもの", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (501, 0, 0, 106401, 0, 14, 80005, 42, "それにあなたも一緒みたいだし\n最後までがんばってみるわ…！", "シェフィ", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (502, 0, 0, 105801, 0, 15, 80005, 42, "それではいつものあれを\nやりましょう！\n準備はいいですかっ？\n…いっきますよー！", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (503, 0, 0, 106001, 0, 15, 80005, 42, "祝！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (504, 0, 0, 105901, 0, 15, 80005, 38, "3.5周年！", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (505, 0, 0, 106401, 0, 15, 80005, 43, "おめでとうございます！", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (506, 0, 0, 190801, 0, 15, 80005, 14, "この日を迎えられたのも\nあなたが『プリンセスコネクト！\nRe:Dive』を遊んでくれている\nおかげです！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (507, 0, 0, 190801, 0, 15, 80005, 15, "ということで\nみなさんからあなたへ一言ずつ\n感謝の言葉をどうぞ！", "カリン", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (508, 0, 0, 105801, 0, 15, 80005, 43, "感謝の言葉ですか？　わたしは\n毎日あなたに感謝してますよ\n【美食殿】の仲間になってくれて…\n一緒にごはんを食べてくれて…", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (509, 0, 0, 105801, 0, 15, 80005, 44, "なにより今でもわたしをぺコリーヌ\nって呼んでくれてありがとうござい\nます。これからもわたしはあなたの\nぺコリーヌです！　やばいですね☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (510, 0, 0, 106001, 0, 15, 80005, 43, "えっ！？　今度はあたし！？\n感謝って…まぁ、そうね…\nあんたにはあたしが\n辛くて苦しい時に助けてもらって…", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (511, 0, 0, 106001, 0, 15, 80005, 44, "でもおかげで色々吹っ切れたわ！\nもしあんたが困ってたら今度は\nあたしが助けてあげるから\nその時はちゃんと言いなさいよ！", "キャル", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (512, 0, 0, 106401, 0, 15, 80005, 44, "ええと…次は私ね\n実はよく覚えてないのだけど\n空から落ちてきた私を受け止めて\nくれたのはあなたなのでしょう？", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (513, 0, 0, 106401, 0, 15, 80005, 45, "最初に私を見つけてくれたのが\nあなたで良かったって思ってるの\nおかげで私は居場所を見つけたから\nあなたがくれたもの、大切にするわ", "シェフィ", 0, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (514, 0, 0, 105901, 0, 15, 80005, 39, "では最後にわたくしから…\nわたくしは主さまの元を離れた日…\nこのように記念日をお祝いする\nことは二度とないと思っていました", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (515, 0, 0, 105901, 0, 15, 80005, 40, "ですが、主さまはわたくしを\n迎えにきてくださり、今もこうして\nおそばにおいてくださっています\nわたくしにとって毎日が記念日です", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (516, 0, 0, 105901, 0, 15, 80005, 41, "わたくしたちの物語は\nまだ続いていきます\nこれからも一緒にページを\n作っていきましょうね", "コッコロ", 4, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (517, 0, 0, 105801, 0, 15, 80005, 45, "それじゃ\nいつものあれでしめますよ！\nみんなで一緒に、さんはい☆", "ペコリーヌ", 3, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (518, 0, 1, 105801, 0, 15, 80005, 46, "これからも\nよろしくおねがいします！", "みんな", 4, "105901,42,106001,45,106401,46,190801,16");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (519, 0, 0, 190804, 1, 0, 60003, 1, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", "カリン", 1, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (520, 1, 0, 0, 1, 0, 60003, 0, "今日の運勢は姫吉！　どんな不可能も可能にできちゃう！　　　　仲間と食卓を囲めばさらに運気上昇よ！　ただし魔物料理以外！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (521, 1, 0, 0, 1, 0, 60003, 0, "今日の運勢は姫吉！　やること全てが最高潮！　やばいですね☆　ラッキーアイテムはおにぎり！　お腹一杯で幸せが続くでしょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (522, 1, 0, 0, 1, 0, 60003, 0, "今日の運勢は姫吉！　羽が生えたように飛躍できる絶好調の運気！新しいことに挑戦するなら今しかないわ！　やってみましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (523, 1, 0, 0, 1, 0, 60003, 0, "今日の運勢は姫吉！　精霊も新年の幸福をお祝いしています！　　主さまの笑顔が見られて、わたくしも幸せいっぱいでございます♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (524, 1, 0, 0, 2, 0, 60003, 0, "今日の運勢は姫吉！　やること全てが上手くいく最高の一日！　　あなたの活躍に先生もにっこりです。いい子いい子♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (525, 2, 0, 0, 1, 0, 60003, 0, "今日の運勢は大吉！　お裁縫好きな女の子のお墨付きです！　　　お世話したがりの妹にめいっぱい愛されちゃうかも！？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (526, 2, 0, 0, 1, 0, 60003, 0, "今日の運勢は大吉！　ラッキーカラーは赤！　　　　　　　　　　湧き上がるアイデアの数々に、高笑いが止まりませんわ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (527, 2, 0, 0, 1, 0, 60003, 0, "今日の運勢は大吉！　ラッキーカラーは鮮やかな黄色！　　　　　さらにシマシマのアイテムを持つと、運気倍増らしいッスよ♪", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (528, 2, 0, 0, 1, 0, 60003, 0, "今日の運勢は大吉！　秘められた力が開花するでしょう！　　　　じゃあ、私の龍眼と力比べしてみようか？　ふふ、冗談だよ～", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (529, 2, 0, 0, 2, 0, 60003, 0, "今日の運勢は大吉！　悩んでいたことが解決しそうです！　　　　たまには勉強も仕事も忘れて、心あたたまる家族と過ごしましょ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (530, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　家の中でゆっくり過ごすのがよさそう！　　ラッキーアイテムはゲームよ！　ベストスコアを更新できるかも？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (531, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　上手くなりたいことに積極的に挑戦してみてサックス好きの妹が、手取り足取りサポートしてくれるかも～？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (532, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　仕事運が急上昇中です！　　　　　　　　　きっと「煉獄に舞う一陣の疾風」の如き活躍ができますよ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (533, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　日頃の努力が報われます！　　　　　　　　親しい友人がいるなら報告してみて。一緒に喜んでくれるはずだ。", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (534, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　ラッキーアイテムはかわいいもの！　　　　ア、アタシはかわいいじゃなくてキレイだってば！　も～っ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (535, 3, 0, 0, 1, 0, 60003, 0, "今日の運勢は中吉！　チャンスを待つと良い結果に！　　　　　　ラッキーアイテムのプリンを食べて、運を呼び込みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (536, 3, 0, 0, 2, 0, 60003, 0, "今日の運勢は中吉！　悩まず行動すれば強運に恵まれる！　　　　守るよりも攻めるが吉だ！　勝負事をするにはいい運勢だな！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (537, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　まだ見ぬ危険が隠れているかも！　　　　　でも安心しろ！　提督が貴公を守ってくれるはずだぞ！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (538, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (539, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　気の向くままに過ごすのが幸せへの近道！　美味い魚を食べて猫を眺めて、自然体で過ごすのはどうだい？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (540, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (541, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　同腹一心の友だちが見つかるかも！　　　　キーワードは「ユニちゃんズ」、記憶に刻みましょう！", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (542, 4, 0, 0, 1, 0, 60003, 0, "今日の運勢は小吉！　周りに流されず、マイペースな一日を！　　ただし寝すぎには注意ぐうたらし過ぎず適度な運動を、だってさ～", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (543, 4, 0, 0, 2, 0, 60003, 0, "今日の運勢は小吉！　無理は禁物、お家で静かにしていましょう　プロぼっちの私が、お家での過ごし方……教えてあげましょうか？", "", 2, "");
