INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (561, 3, 0, 0, 1, 0, 60004, 0, "今日の運勢は中吉！　健康に気を遣って気持ちのいい一年を！\n体に不調があるときは遠慮なく言いなさい、隅々まで調べてあげる", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (562, 3, 0, 0, 1, 0, 60004, 0, "今日の運勢は中吉！　歌を口ずさみ、幸運を呼び込もう！\n幸運になれるかは分からないけど……一緒に、歌いましょ？", "", 2, "");
INSERT INTO `v1_e5fc900b6c977ed3c809dd36eb0e265cdbb8fa2566b870ed5e64fa5d821607d7` VALUES (563, 3, 0, 0, 1, 0, 60004, 0, "今日の運勢は中吉！　誰かに尽くすことで掴める幸せもあるかも？\n人事を尽くして天命を待つ！　さ、年始もバリバリ働きますわよ♪", "", 2, "");
